$('#arcade-sound').onclick=()=>{arcade.sound=!arcade.sound;$('#arcade-sound').textContent=arcade.sound?'♫ Sound on':'♫ Sound off';$('#arcade-sound').setAttribute('aria-pressed',String(arcade.sound));if(arcade.sound){try{arcade.audio ||= new (window.AudioContext||window.webkitAudioContext)();arcade.audio.resume().catch(()=>{});tone(true);}catch{arcade.sound=false;$('#arcade-sound').textContent='Sound unavailable';$('#arcade-sound').setAttribute('aria-pressed','false');}}};
$('#arcade-motion').onclick=()=>{arcade.reduced=!arcade.reduced;$('#arcade-motion').textContent=arcade.reduced?'Motion off':'Motion on';$('#arcade-motion').setAttribute('aria-pressed',String(!arcade.reduced));document.body.classList.toggle('still-games',arcade.reduced);if(arcade.reduced)arcade.particles=[];renderArcade();};
document.body.classList.toggle('still-games',arcade.reduced);
function tone(good,win=false){if(!arcade.sound||!arcade.audio)return;const a=arcade.audio,notes=win?[523,659,784,1047]:good?[660,880]:[230,160];notes.forEach((hz,i)=>{const oscillator=a.createOscillator(),gain=a.createGain(),start=a.currentTime+i*.1;oscillator.type=good?'sine':'triangle';oscillator.frequency.value=hz;gain.gain.setValueAtTime(0,start);gain.gain.linearRampToValueAtTime(.055,start+.015);gain.gain.exponentialRampToValueAtTime(.001,start+.22);oscillator.connect(gain);gain.connect(a.destination);oscillator.start(start);oscillator.stop(start+.24);});}
function circle(x,y,r,color){cx.fillStyle=color;cx.beginPath();cx.arc(x,y,r,0,Math.PI*2);cx.fill();}
function ellipse(x,y,rx,ry,color){cx.fillStyle=color;cx.beginPath();cx.ellipse(x,y,rx,ry,0,0,Math.PI*2);cx.fill();}
function box(x,y,w,h,r,color){cx.fillStyle=color;cx.beginPath();cx.roundRect(x,y,w,h,r);cx.fill();}
function line(x1,y1,x2,y2,color,width=4){cx.strokeStyle=color;cx.lineWidth=width;cx.lineCap='round';cx.beginPath();cx.moveTo(x1,y1);cx.lineTo(x2,y2);cx.stroke();}
function label(text,x,y,size=18,color='#fff',align='center'){cx.font=`800 ${size}px "Segoe UI", sans-serif`;cx.fillStyle=color;cx.textAlign=align;cx.textBaseline='middle';cx.fillText(text,x,y);}
function polygon(points,color){cx.fillStyle=color;cx.beginPath();points.forEach(([x,y],i)=>i?cx.lineTo(x,y):cx.moveTo(x,y));cx.closePath();cx.fill();}
function star(x,y,r,color,rotation=0){const pts=[];for(let i=0;i<10;i++){const a=i*Math.PI/5-Math.PI/2+rotation,d=i%2?r*.45:r;pts.push([x+Math.cos(a)*d,y+Math.sin(a)*d]);}polygon(pts,color);}
function cloud(x,y,s=1){ellipse(x,y,49*s,16*s,'#ffffffab');circle(x-20*s,y-10*s,21*s,'#ffffffab');circle(x+12*s,y-16*s,28*s,'#ffffffab');}
function sky(world){const g=cx.createLinearGradient(0,0,0,300);g.addColorStop(0,world.sky[0]);g.addColorStop(1,world.sky[1]);cx.fillStyle=g;cx.fillRect(0,0,1100,300);}
function stars(){for(let i=0;i<44;i++){const x=(i*137+43)%1100,y=(i*73+17)%220;circle(x,y,1.2+Math.sin(arcade.time*.8+i)*.6,'#ffffffa0');}}
