function drawOcean(){for(let i=0;i<28;i++){const x=(i*89+30)%1100,y=300-((arcade.time*18+i*37)%310);cx.strokeStyle='#93f4eb44';cx.lineWidth=2;cx.beginPath();cx.arc(x,y,4+i%4*3,0,Math.PI*2);cx.stroke();}for(let i=0;i<15;i++){cx.strokeStyle=i%2?'#28bca5':'#27a294';cx.lineWidth=9;cx.beginPath();cx.moveTo(i*85,305);cx.quadraticCurveTo(i*85+Math.sin(arcade.time+i)*25,245,i*85+12,228-i%3*20);cx.stroke();}ellipse(550,310,650,60,'#d9b886');octopus(170,148+Math.sin(arcade.time)*12);for(let i=0;i<6;i++){const x=390+i*103;if(i<game.correct){polygon([[x-16,145],[x-34,132],[x-34,158]],'#ffce67');ellipse(x,145+Math.sin(arcade.time*2+i)*8,25,13,'#ffce67');circle(x+14,141,3,'#253963');}else{cx.save();cx.translate(x,165+Math.sin(arcade.time+i)*12);cx.rotate(Math.sin(arcade.time+i)*.15);box(-12,-25,24,48,5,'#9fc0d999');box(-7,-33,14,10,2,'#cfdfeb');cx.restore();}}label(`${game.correct} RESCUES · KEEP THE OCEAN BRIGHT`,630,44,22,'#b3fff0');}
