function drawLava(){stars();polygon([[20,290],[190,73],[350,290]],'#623551');polygon([[132,150],[190,73],[248,151],[201,139],[172,156]],'#ffbe57');for(let i=0;i<8;i++){const x=150+i*123,y=250-i*19;box(x,y,90,22,7,'#65516b');line(x+5,y,x+85,y,'#a497b5',4);}cx.fillStyle='#ff653b';cx.beginPath();cx.moveTo(0,300);for(let x=0;x<=1100;x+=15)cx.lineTo(x,278+Math.sin(x*.018+arcade.time*2)*7);cx.lineTo(1100,300);cx.fill();const level=Math.max(0,Math.min(7,arcade.score/150));hamster(192+level*123,202-level*19,'#ffc94e',.6,1,false);for(let i=0;i<6;i++){const x=390+i*115;polygon([[x,54],[x+11,67],[x,81],[x-11,67]],'#ffdf72');}label('BIG THINKING. BOLD MOVES.',650,30,22,'#fff1ac');}
function drawBattle(){stars();for(let i=0;i<9;i++){const x=i*141;box(x,185-i%3*25,75,115+i%3*25,3,'#193c65');for(let k=0;k<4;k++)box(x+14+k%2*27,199-i%3*25+Math.floor(k/2)*26,10,12,1,'#69a6bb55');}box(0,274,1100,26,0,'#12314f');robot(850,152,arcade.event==='miss'&&arcade.eventAge<1);hamster(160,198,'#41daba',.9,1,false);box(160,196,87,22,8,'#d4e8e9');box(222,191,35,32,5,'#539fb9');const remaining=Math.max(0,1-game.correct/game.items.length);box(711,26,278,18,9,'#13283e');box(715,30,270*remaining,10,5,'#ff6a90');label('ROGUE ROBOT ENERGY',850,62,13,'#c5e9ff');for(let i=0;i<3;i++){polygon([[100+i*55,50],[121+i*55,59],[117+i*55,82],[100+i*55,96],[83+i*55,82],[79+i*55,59]],i<game.lives?'#63f1d0':'#4f6482');}if(arcade.event==='hit'&&arcade.eventAge<1){const x=250+Math.min(1,arcade.eventAge*2)*570;line(x-70,204,x,204,'#9affda',12);circle(x,204,14,'#fff7a3');}}
function drawCity(){stars();circle(957,58,32,'#ffe49b');circle(970,47,29,'#343260');for(let i=0;i<10;i++){const x=i*119,h=85+i%3*28;box(x,300-h,107,h,4,'#1b2451');for(let j=0;j<6;j++)box(x+17+j%3*28,315-h+Math.floor(j/3)*30,12,18,1,i<game.correct?'#ffd96d':'#5c639260');}cx.save();cx.translate(arcade.hinted?700:400,104);cx.rotate(Math.sin(arcade.time*.7)*.12);cx.strokeStyle='#ffc96f';cx.lineWidth=10;cx.beginPath();cx.arc(0,0,43,0,Math.PI*2);cx.stroke();circle(0,0,36,'#82c8f233');line(31,34,73,83,'#be8264',14);label('?',0,2,39,'#fff5ce');cx.restore();label('THE NEXT CLUE IS YOURS',580,41,22,'#e7dcff');}
function burst(good,win=false){arcade.event=win?'win':good?'hit':'miss';arcade.eventAge=0;tone(good,win);if(arcade.reduced)return;const colors=good?['#ffe174','#68f6da','#ff7cba','#9b8cff','#fff']:['#ff816d','#ffce8f'];const count=win?100:good?42:16;for(let i=0;i<count;i++)arcade.particles.push({x:550,y:win?90:165,vx:(Math.random()-.5)*(win?720:460),vy:-80-Math.random()*240,life:1.2+Math.random(),color:colors[i%colors.length],size:4+Math.random()*7,spin:Math.random()*7});arcade.particles=arcade.particles.slice(-180);}
function syncArcade(){if(!game)return;if(arcade.owner!==game){arcade.owner=game;arcade.particles=[];arcade.seenAttempts=0;arcade.seenMatches=0;arcade.seenDone=false;arcade.rope=0;arcade.racers=[0,0];arcade.progress=0;arcade.score=game.score;arcade.event='';arcade.eventAge=10;arcade.time=0;}if(game.attempts>arcade.seenAttempts){const good=game.lesson.format==='match'?game.matched.length>arcade.seenMatches:game.feedbackGood;if(game.lesson.format!=='corners')burst(good);arcade.seenAttempts=game.attempts;arcade.seenMatches=game.matched.length;}if(game.done&&!arcade.seenDone){if(game.lesson.format==='earth'&&game.session.health<=0)burst(false);else if(game.lesson.format!=='survival'||game.lives>0)burst(true,true);arcade.seenDone=true;}document.body.dataset.world=game.lesson.format;}
function stepArcade(dt){if(!game)return;syncArcade();if(!arcade.reduced)arcade.time+=dt;arcade.eventAge+=dt;for(const p of game.tug||[])if(p.reaction){p.reaction.age+=dt;if(p.reaction.age>=1.8)p.reaction=null;}const ease=arcade.reduced?1:1-Math.exp(-dt*6);arcade.rope+=(game.rope-arcade.rope)*ease;arcade.progress+=(game.correct/game.items.length-arcade.progress)*ease;arcade.score+=(game.score-arcade.score)*ease;for(let i=0;i<2;i++)arcade.racers[i]+=(game.teams[i]/game.items.length-arcade.racers[i])*ease;for(const p of arcade.particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=230*dt;p.life-=dt;p.spin+=dt*4;}arcade.particles=arcade.particles.filter(p=>p.life>0);}
function renderArcade(){if(!game||ui.view!=='player')return;syncArcade();const world=WORLDS[game.lesson.format];cx.save();sky(world);if(game.lesson.format!=='relay'&&!arcade.reduced&&arcade.event==='miss'&&arcade.eventAge<.35)cx.translate(Math.sin(arcade.eventAge*65)*5,0);({quiz:drawRocket,tug:drawTug,relay:drawRace,sort:drawOcean,match:drawPotion,order:drawBridge,board:drawTreasure,wager:drawLava,survival:drawBattle,clue:drawCity,kingdom:drawModeWorld,corners:drawModeWorld,earth:drawModeWorld})[game.lesson.format]();for(const p of arcade.particles){cx.save();cx.globalAlpha=Math.min(1,p.life);cx.translate(p.x,p.y);cx.rotate(p.spin);box(-p.size/2,-p.size/2,p.size,p.size*.55,1,p.color);cx.restore();}if(arcade.eventAge<1.8&&(game.lesson.format!=='relay'||arcade.event==='win')){const text=arcade.event==='win'?'MISSION COMPLETE!':arcade.event==='hit'?['quiz','survival'].includes(game.lesson.format)?'POWER UP!':'NICE MOVE!':'TRY THE NEXT ONE!';const width=Math.min(540,text.length*22+60);box(550-width/2,105,width,64,18,arcade.event==='miss'?'#992e47ed':'#242353ed');label(text,550,137,30,arcade.event==='miss'?'#fff3cf':'#ffea7d');}cx.restore();}
drawCanvas=renderArcade;
function decorateArcade(){if(!game||ui.view!=='player')return;const world=WORLDS[game.lesson.format];$('#player').style.setProperty('--world',world.color);$('#player').style.setProperty('--spark',world.accent);mission.innerHTML=`<span>${world.emoji}</span><strong>${esc(world.name)}</strong><p>${esc(world.mission)}</p>`;$('#play-format').textContent=world.name;$('#arena').classList.toggle('answer-hit',game.answered&&game.feedbackGood);$('#arena').classList.toggle('answer-miss',game.answered&&!game.feedbackGood);$('#arena').classList.toggle('game-finished',game.done);
 if(game.lesson.format==='board')document.querySelectorAll('[data-board]').forEach(b=>{const icon=document.createElement('i');icon.textContent=b.disabled?'✨':'🎁';icon.setAttribute('aria-hidden','true');b.prepend(icon);});
 if(game.lesson.format==='match')document.querySelectorAll('[data-left],[data-right]').forEach(b=>{const id=Number(b.dataset.left??b.dataset.right);b.classList.toggle('pair-complete',game.matched.includes(id));});
 if(game.lesson.format==='sort'&&!game.answered){const prompt=$('#question-prompt');if(prompt){prompt.draggable=true;prompt.classList.add('sorting-object');prompt.setAttribute('title','Drag to a category, or click a category below');prompt.addEventListener('dragstart',e=>{e.dataTransfer.setData('text/plain','oxford-sort');e.dataTransfer.effectAllowed='move';});}document.querySelectorAll('[data-answer]').forEach(b=>{b.ondragover=e=>{e.preventDefault();b.classList.add('drop-ready');};b.ondragleave=()=>b.classList.remove('drop-ready');b.ondrop=e=>{e.preventDefault();if(e.dataTransfer.getData('text/plain')==='oxford-sort')b.click();};});}
 renderArcade();}
const plainEditor=openEditor;function decorateEditor(){if(!draft)return;$('#format-name').textContent=WORLDS[draft.format].name;$('#format-icon').textContent=WORLDS[draft.format].emoji;}
openEditor=function(lesson){plainEditor(lesson);decorateEditor();};
const plainRenderGame=renderGame;renderGame=function(){plainRenderGame();decorateArcade();};
const plainLibrary=renderLibrary;renderLibrary=function(){plainLibrary();document.querySelectorAll('.game-card').forEach(card=>{const id=card.querySelector('[data-edit]').dataset.edit,g=findLesson(id),world=WORLDS[g.format],art=card.querySelector('.card-art');art.style.setProperty('--card-world',world.color);art.style.setProperty('--card-spark',world.accent);art.innerHTML=`<span class="format-tag">${esc(world.name)}</span><span class="preview-orbit" aria-hidden="true"></span><span class="preview-character" aria-hidden="true">${world.emoji}</span><span class="preview-star" aria-hidden="true">✦</span><span class="preview-small" aria-hidden="true">${g.format==='tug'?'🐹':g.format==='relay'?'🐹':'✧'}</span>`;});};
window.advanceTime=ms=>{arcade.manual=true;const steps=Math.max(1,Math.ceil(Math.min(Number(ms)||0,10000)/16));for(let i=0;i<steps;i++)stepArcade((Number(ms)||0)/steps/1000);renderArcade();};
const plainState=window.render_game_to_text;window.render_game_to_text=()=>{const s=JSON.parse(plainState());if(game&&ui.view==='player')s.animation={world:WORLDS[game.lesson.format].name,time:Math.round(arcade.time*100)/100,event:arcade.event,particles:arcade.particles.length,ropePosition:Math.round(arcade.rope*100)/100,hamsterReactions:game.tug?.map(p=>p.reaction?{kind:p.reaction.kind,age:Math.round(p.reaction.age*100)/100}:null),racerProgress:arcade.racers.map(n=>Math.round(n*100)/100),reducedMotion:arcade.reduced,sound:arcade.sound};return JSON.stringify(s);};
function animate(now){const dt=Math.min(.04,(now-(arcade.last||now))/1000);arcade.last=now;if(ui.view==='player'&&!document.hidden&&!arcade.manual){stepArcade(dt);renderArcade();}arcade.raf=requestAnimationFrame(animate);}
window.addEventListener('pagehide',()=>{cancelAnimationFrame(arcade.raf);arcade.audio?.suspend().catch(()=>{});});
renderLibrary();if(ui.view==='editor')decorateEditor();if(ui.view==='player')renderGame();arcade.raf=requestAnimationFrame(animate);
